import * as ecs from "@8thwall/ecs";
import { gameData } from "../core/game-data";


// --------------------------------------------------
// Remove old controls
// --------------------------------------------------

function clearControls(){

  document
  .querySelectorAll(".cyberwrap-control")
  .forEach(
    el=>el.remove()
  );

}



// --------------------------------------------------
// Button creator
// --------------------------------------------------

function createButton(
  text:string,
  style:string
){

  const button =
  document.createElement("button");


  button.className =
  "cyberwrap-control";


  button.innerHTML=text;


  button.style.cssText=style;


  document.body.appendChild(button);


  return button;

}




// --------------------------------------------------
// Component
// --------------------------------------------------

ecs.registerComponent({

name:"joystick",


stateMachine:({defineState})=>{


defineState("ready")

.initial()


.onEnter(()=>{


console.log("[Controls] Initializing");


clearControls();



// ==================================================
// INPUT STATE
// ==================================================

let steering = 0;

let throttle = 0;



function updateInput(){

gameData.input.steering =
steering;


gameData.input.throttle =
throttle;

}



// ==================================================
// STEERING WHEEL
// ==================================================

const wheel =
document.createElement("img");


wheel.src =
"./assets/steering.png";


wheel.className =
"cyberwrap-control";


wheel.style.cssText=`

position:fixed;

left:25px;

bottom:25px;

width:150px;

height:120px;

opacity:1;

z-index:99999;

touch-action:none;

user-select:none;

-webkit-user-select:none;

background:
rgba(255,255,255,.15);

border-radius:50%;

filter:
drop-shadow(0 5px 10px black);

`;



document.body.appendChild(wheel);



let dragging=false;

let wheelRotation=0;



function updateWheel(
e:PointerEvent
){

const rect =
wheel.getBoundingClientRect();


const centerX =
rect.left + rect.width / 2;


const dx =
e.clientX - centerX;


// Visual wheel movement
const wheelSteering =
dx /
(rect.width / 2);


const clampedWheel =
Math.max(
-1,
Math.min(
1,
wheelSteering
)
);


// Rotate image naturally
wheelRotation =
clampedWheel * 120;


wheel.style.transform =
`
rotate(${wheelRotation}deg)
`;



// Send opposite value to truck
steering =
-clampedWheel;


gameData.input.steering =
steering;


}



wheel.addEventListener(

"pointerdown",

(e)=>{


e.preventDefault();


dragging=true;


wheel.setPointerCapture(
e.pointerId
);


updateWheel(e);


}

);



wheel.addEventListener(

"pointermove",

(e)=>{


if(!dragging)
return;


updateWheel(e);


}

);



function releaseWheel(){


dragging=false;


steering=0;


gameData.input.steering=0;


wheel.style.transform=
"rotate(0deg)";


}



wheel.addEventListener(
"pointerup",
releaseWheel
);


wheel.addEventListener(
"pointercancel",
releaseWheel
);


wheel.addEventListener(
"lostpointercapture",
releaseWheel
);





// ==================================================
// GAS BUTTON
// ==================================================

const gas =
createButton(

"GAS",

`

position:fixed;

right:30px;

bottom:120px;

width:100px;

height:70px;

border-radius:22px;

background:

rgba(255,90,0,.75);

color:white;

font-size:22px;

font-weight:bold;

border:none;

z-index:99999;

touch-action:none;

`

);





// ==================================================
// REV BUTTON
// ==================================================

const rev =
createButton(

"REV",

`

position:fixed;

right:30px;

bottom:35px;

width:100px;

height:60px;

border-radius:22px;

background:

rgba(255,255,255,.2);

color:white;

font-size:20px;

font-weight:bold;

border:none;

z-index:99999;

touch-action:none;

`

);






// ==================================================
// GAS / REV INPUT
// ==================================================


gas.addEventListener(
"pointerdown",

(e)=>{

e.preventDefault();


throttle=1;


updateInput();

}

);



rev.addEventListener(
"pointerdown",

(e)=>{

e.preventDefault();


throttle=-1;


updateInput();

}

);





function stopThrottle(){

throttle=0;

updateInput();

}



gas.addEventListener(
"pointerup",
stopThrottle
);


rev.addEventListener(
"pointerup",
stopThrottle
);


gas.addEventListener(
"pointercancel",
stopThrottle
);


rev.addEventListener(
"pointercancel",
stopThrottle
);





// ==================================================
// SAFETY RESET
// ==================================================

function reset(){

steering=0;

throttle=0;


gameData.input.steering=0;

gameData.input.throttle=0;


wheel.style.transform=
"rotate(0deg)";

}



window.addEventListener(
"blur",
reset
);



document.addEventListener(
"visibilitychange",

()=>{

if(document.hidden)
reset();

}

);



console.log(
"[Controls] Ready"
);



});


}


});
